use super::*;
use semio_framework_os_spr::{ActorId,ArtifactId,ArtifactDiff,InverseMutation,SchemaId,InputReplacement};
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:262144,maximum_depth:4096}}
fn observed<T>(run:impl FnOnce()->(T,RetainedCloneProgress))->T{let((value,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);assert!(p.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));value}
fn close<T:semio_framework_value::retirement::RetireOwned>(value:T){let mut value=Some(value);let mut owner=RetainedCloneClose::default();for index in 0..100000{if value.is_none()&&owner.is_empty(){return}observed(||{let step=if let Some(step)=owner.begin_granted(&mut value,grant()).unwrap(){step}else{owner.step_granted(grant()).unwrap()};((),step.progress())});assert!(index<99999)}panic!("original canonical overlay fixture remained owned")}
#[test]
fn original_replay_supersessions_move_original_payloads_and_retire_replaced_rows_at_each_cancel_prefix(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){for cut in [0,1,2,3,8,16,32,64,128,usize::MAX]{let scope=case["scope"].as_str();let payload=vec![71;case["payloadBytes"].as_u64().unwrap()as usize];let pointer=payload.as_ptr();let mut drafts=HistoryInputDrafts::from([(MutationId("operation-a".into()),InputReplacement::Input{schema:"original.schema".into(),payload}),(MutationId("operation-b".into()),InputReplacement::Withdrawn)]);let actor=ActorId(case["actor"].as_str().unwrap().into());let event=MutationEnvelope{mutation_id:MutationId(case["transition"].as_str().unwrap().into()),document_id:ArtifactId("original-document".into()),actor,dependencies:Vec::new(),observed:None,target:Vec::new(),diff:ArtifactDiff{schema:SchemaId(semio_framework_os_spr::HISTORY_TRANSITION_SCHEMA.into()),payload:Default::default()},inverse:InverseMutation{schema:SchemaId(semio_framework_os_spr::HISTORY_TRANSITION_SCHEMA.into()),payload:Default::default()},timestamp:HybridLogicalTimestamp::new(71,19),transaction:None,verb:None,line:None};let mut map=EffectiveSupersessions::new();map.insert(MutationId("operation-a".into()),EffectiveSupersession{transition_id:"prior-transition".into(),actor:Default::default(),timestamp:HybridLogicalTimestamp::new(1,1),scope:None,replacement:InputReplacement::Input{schema:"prior.schema".into(),payload:vec![19;4099]}});let mut owner=OriginalReplaySupersessions::default();for index in 0..100000{if index==cut||owner.prepared(){break}let d=owner.demands(&drafts,&map,&event,scope,4096).unwrap();for axis in 0..5{let amount=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if amount==0{continue}let mut g=grant();match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes=amount-1,2=>g.maximum_capacity_bytes=amount-1,3=>g.maximum_release_bytes=amount-1,_=>g.maximum_depth=amount-1}let before=(drafts.mutation_epoch(),map.mutation_epoch(),owner.phase);observed(||{let p=owner.advance(&mut drafts,&mut map,&event,scope,g).unwrap();assert_eq!(p,Default::default());((),p)});assert_eq!((drafts.mutation_epoch(),map.mutation_epoch(),owner.phase),before);}observed(||{let p=owner.advance(&mut drafts,&mut map,&event,scope,grant()).unwrap();((),p)});assert!(index<99999)}if cut==usize::MAX{assert!(owner.prepared()&&drafts.is_empty());let targets:Vec<_>=map.iter().map(|(key,_)|key.0.as_str()).collect();assert_eq!(serde_json::to_value(targets).unwrap(),case["expectedTargets"]);for (_,row) in map.iter(){assert_eq!(row.transition_id,event.mutation_id.0);assert_eq!(row.actor.as_ptr(),event.actor.0.as_ptr());assert_eq!(row.scope.as_deref(),scope);assert_eq!(row.timestamp,event.timestamp);}let InputReplacement::Input{payload,..}=&map.get("operation-a").unwrap().replacement else{panic!("original input remains typed")};assert_eq!(payload.as_ptr(),pointer);assert_eq!(payload.len(),case["payloadBytes"].as_u64().unwrap()as usize);assert_eq!(map.get("operation-b").unwrap().replacement,InputReplacement::Withdrawn);}for index in 0..100000{if owner.terminal_is_empty(){break}observed(||{let step=owner.close_step(grant()).unwrap();((),step.progress())});assert!(index<99999)}assert!(owner.terminal_is_empty());close((drafts,map,event));}}}
